from typing import Protocol, runtime_checkable

# 1. Define a runtime-checkable Protocol named Scorer with the method score(self, text: str) -> float.

class LengthScorer:
    def score(self, text):
        return float(len(text))

class VowelScorer:
    def score(self, text):
        return float(sum(ch in "aeiou" for ch in text))

class Rogue:
    pass

def best(candidates, text):
    """Return the class name of the candidate with the highest score for text.
    Ignore anything that is not a Scorer. (Assume no ties.)"""
    pass

print(best([Rogue(), VowelScorer(), LengthScorer()], "protocols"))

practice_challenges.test_code:
assert Scorer._is_protocol, "Scorer must be a typing.Protocol"
assert isinstance(LengthScorer(), Scorer) and not isinstance(Rogue(), Scorer), "Scorer must be runtime checkable and need score()"

class Negative:
    def score(self, text):
        return -1.0

class Ten:
    def score(self, text):
        return 10.0

assert isinstance(Negative(), Scorer), "classes are accepted by shape, no inheritance needed"
assert best([Rogue(), Negative()], "x") == "Negative", "non-scorers are skipped even if they come first"
assert best([Negative(), Ten(), Rogue()], "x") == "Ten", "highest score wins"
assert best([Rogue(), LengthScorer(), VowelScorer()], "queueing") == "LengthScorer"

