import io
from typing import Protocol, runtime_checkable

@runtime_checkable
class Closeable(Protocol):
    def close(self) -> None: ...

class Conn:
    def close(self):
        pass

class Note:
    pass

class BadClose:
    def close(self, a, b, c):
        pass

for obj in [Conn(), Note(), io.StringIO(), BadClose()]:
    print(type(obj).__name__, isinstance(obj, Closeable))

